const fs=require('node:fs');const crypto=require('node:crypto');const mysql=require('/opt/anqi/business/node_modules/mysql2/promise');
(async()=>{const vars={};for(const line of fs.readFileSync('/opt/anqi/shared/business.env','utf8').split(/\r?\n/)){const m=line.match(/^([A-Z_]+)=(.*)$/);if(m)vars[m[1]]=m[2].replace(/^['"]|['"]$/g,'')};const c=await mysql.createConnection({host:'127.0.0.1',port:Number(vars.DB_PORT),user:vars.DB_USER,password:vars.DB_PASSWORD,database:vars.DB_NAME});try{await c.beginTransaction();const [rows]=await c.query('SELECT id,payload FROM anqi_audit');let fixed=0;for(const row of rows){const p=JSON.parse(row.payload);if(!p.id){p.id=row.id||crypto.randomUUID();await c.query('UPDATE anqi_audit SET payload=? WHERE id=?',[JSON.stringify(p),row.id]);fixed++}}await c.commit();console.log(JSON.stringify({auditRows:rows.length,fixed}));}catch(e){await c.rollback();throw e}finally{await c.end()}})().catch(e=>{console.error(e.message);process.exit(1)})
